    const txt=String(pill&&pill.textContent||'');
    const m=txt.match(/(\d+)\s*\/\s*(\d+)/);
    let done=m?Number(m[1]):-1;
    let total=m?Number(m[2]):-1;
    if(total<=0){
      // Únicamente como respaldo cuando el núcleo no presenta contador numérico.
      const mission=scroll.querySelectorAll('.v94-mentalist-step,.v69-routine-item,.v85-sung-item,.v83-legal-item');
      if(mission.length){total=mission.length;done=Array.from(mission).filter(x=>x.classList.contains('done')||x.classList.contains('completed')||x.getAttribute('aria-pressed')==='true').length;}
