 const count=progress();const total=count?.total||wraps.length,done=count?.done??wraps.filter(w=>w.querySelector('.v32-mission-item.done')).length;
 const pct=total>0?Math.max(0,Math.min(100,Math.round(done/total*100))):0;
 function changeText(selector,value){const e=pro.querySelector(selector);if(e&&e.textContent!==value)e.textContent=value}
