const TF_AUDIO_T16_JS="/* T16: la comprobación de música guardada se realiza sin pantallazos. */
(function(){
'use strict';
if(window.__tfSilentAudioVerifyT16)return;
window.__tfSilentAudioVerifyT16=true;
const ID='tfAudioGateV13057';
function watchGate(gate){
  if(gate.dataset.tfSilentWatchT16==='1')return;
  gate.dataset.tfSilentWatchT16='1';
  const status=gate.querySelector('.tf-audio-gate-status');
  if(!status)return;
  const assess=()=>{
    const label=String(status.textContent||'').trim();
    const realDownload=/^Descargando música\s+\d+\s+de\s+\d+/i.test(label);
    const needsAction=/^La música debe quedar descargada completamente/i.test(label);
    // No mostrar un diálogo mientras solo se verifica un paquete ya almacenado.
    gate.classList.toggle('tf-audio-real-download-t16',realDownload||needsAction);
  };
  const statusObserver=new MutationObserver(assess);
  statusObserver.observe(status,{childList:true,characterData:true,subtree:true});
  assess();
}
function ready(){
  const body=document.body;if(!body)return;
  const found=document.getElementById(ID);
  if(found){watchGate(found);return;}
  const observer=new MutationObserver(records=>{
    for(const record of records){
      for(const node of record.addedNodes){
        if(node.nodeType!==1)continue;
        const gate=node.id===ID?node:node.querySelector?.('#'+ID);
        if(gate){observer.disconnect();watchGate(gate);return;}
      }
    }
  });
  observer.observe(body,{childList:true});
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ready,{once:true});
else ready();
})();
