/* T34 · Recuperación exclusiva del almacén de música. No modifica IndexedDB global
   ni borra bases, cachés, hábitos, tareas, preferencias o credenciales. */
const TF34_INSTALL_KEY='tf_audio_install_device_t34';
const TF34_RESET_KEY='tf_audio_reset_device_t34';
const TF34_BACKEND_KEY='tf_audio_backend_device_t34';
const TF34_INSTALL_META='device_install_t34';
const TF34_CACHE_NAME='taskflow_audio_recovery_t34';
const tf34Memory={tracks:new Map(),meta:new Map()};
let tf34DialogAllowed=false;
function tf34LocalState(){try{const s=JSON.parse(localStorage.getItem(TF34_INSTALL_KEY)||'null');return s&&typeof s==='object'?s:null}catch(_){return null}}
function tf34ResetStamp(){
 let stamp=0;
 try{
  stamp=Number(localStorage.getItem(TF34_RESET_KEY))||0;
  for(let i=0;i<localStorage.length;i++){
   const key=localStorage.key(i);
   if(key&&key.startsWith('taskflow_global_reset_applied_v120_'))stamp=Math.max(stamp,Number(localStorage.getItem(key))||0);
  }
 }catch(_){}
 return stamp;
}
function tf34Timed(promise,ms,label){
 return new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error(label)),ms);Promise.resolve(promise).then(value=>{clearTimeout(timer);resolve(value)},error=>{clearTimeout(timer);reject(error)})});
}
function tf34NativeOpen(){
 return new Promise((resolve,reject)=>{
  let finished=false,request;
  const timer=setTimeout(()=>finish(new Error('El almacén de música no respondió.')),6000);
  function finish(error,db){
   if(finished){if(db)try{db.close()}catch(_){}return}
   finished=true;clearTimeout(timer);if(error)reject(error);else resolve(db);
  }
  try{
   if(!window.indexedDB){finish(new Error('IndexedDB no disponible para la música.'));return}
   request=window.indexedDB.open(DB_NAME,DB_VERSION);
   request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains(STORE_TRACKS))db.createObjectStore(STORE_TRACKS,{keyPath:'id'});if(!db.objectStoreNames.contains(STORE_META))db.createObjectStore(STORE_META,{keyPath:'key'})};
   request.onsuccess=()=>finish(null,request.result);
   request.onerror=()=>finish(request.error||new Error('No se pudo abrir el almacén de música.'));
   request.onblocked=()=>finish(new Error('El almacén de música está bloqueado.'));
  }catch(error){finish(error)}
 });
}
function tf34NativeGet(db,store,key){
 return new Promise((resolve,reject)=>{
  let tx;try{tx=db.transaction(store,'readonly');const r=tx.objectStore(store).get(key);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error);tx.onabort=()=>reject(tx.error||new Error('Lectura de música cancelada.'))}catch(e){reject(e)}
 });
}
function tf34NativePut(db,store,value){
 return new Promise((resolve,reject)=>{
  try{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(value);tx.oncomplete=()=>resolve(true);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Escritura de música cancelada.'))}catch(e){reject(e)}
 });
}
function tf34CacheKey(store,key){return new Request('https://taskflow-audio.invalid/t34/'+encodeURIComponent(store)+'/'+encodeURIComponent(key))}
function tf34FileName(store,key){return encodeURIComponent(store)+'_'+encodeURIComponent(key)}
async function tf34ReadFile(dir,name){try{return await(await dir.getFileHandle(name)).getFile()}catch(e){if(e&&e.name==='NotFoundError')return null;throw e}}
async function tf34WriteFile(dir,name,value){
 const file=await dir.getFileHandle(name,{create:true});const writer=await file.createWritable();
 try{await writer.write(value);await writer.close()}catch(e){try{await writer.abort()}catch(_){}throw e}
}
async function tf34DirectGet(handle,store,key){
 if(handle.mode==='indexeddb')return tf34Timed(tf34NativeGet(handle.native,store,key),10000,'El almacén de música no respondió.');
 if(handle.mode==='cache'){
  const response=await tf34Timed(handle.cache.match(tf34CacheKey(store,key)),5000,'La caché de música no respondió.');
  if(!response)return null;
  if(store!==STORE_TRACKS)return response.json();
  const metadata=response.headers.get('x-taskflow-audio-record');if(!metadata)return null;
  const row=JSON.parse(decodeURIComponent(metadata));row.blob=await response.blob();return row;
 }
 if(handle.mode==='opfs'){
  const base=tf34FileName(store,key),metadata=await tf34ReadFile(handle.dir,base+'.json');if(!metadata)return null;
  const row=JSON.parse(await metadata.text());
  if(store===STORE_TRACKS){const blob=await tf34ReadFile(handle.dir,base+'.audio');if(!blob)return null;row.blob=blob}
  return row;
 }
 return null;
}
async function tf34DirectPut(handle,store,value){
 if(handle.mode==='indexeddb')return tf34Timed(tf34NativePut(handle.native,store,value),15000,'No se pudo terminar el guardado de música.');
 if(handle.mode==='cache'){
  const key=store===STORE_TRACKS?value.id:value.key;
  let response;
  if(store===STORE_TRACKS){const record={...value};delete record.blob;response=new Response(value.blob,{headers:{'Content-Type':value.blob.type||'audio/mpeg','x-taskflow-audio-record':encodeURIComponent(JSON.stringify(record))}})}
  else response=new Response(JSON.stringify(value),{headers:{'Content-Type':'application/json'}});
  await tf34Timed(handle.cache.put(tf34CacheKey(store,key),response),15000,'La caché de música no pudo completar el guardado.');return true;
 }
 if(handle.mode==='opfs'){
  const key=store===STORE_TRACKS?value.id:value.key,base=tf34FileName(store,key),record={...value};
  if(store===STORE_TRACKS){delete record.blob;await tf34Timed(tf34WriteFile(handle.dir,base+'.audio',value.blob),15000,'No se pudo guardar el archivo de música.')}
  await tf34Timed(tf34WriteFile(handle.dir,base+'.json',JSON.stringify(record)),5000,'No se pudo guardar la verificación de música.');return true;
 }
 return true;
}
function tf34RememberBackend(handle){try{if(handle.mode!=='memory')localStorage.setItem(TF34_BACKEND_KEY,handle.mode)}catch(_){}}
async function tf34SelectStore(handle,candidates,error){
 if(error)console.warn('TaskFlow: recuperación del almacén de música',error);
 try{if(handle.native)handle.native.close()}catch(_){}handle.native=null;
 for(const mode of candidates){
  handle.mode=mode;handle.cache=null;handle.dir=null;handle.generation++;
  try{
   if(mode==='indexeddb')handle.native=await tf34NativeOpen();
   else if(mode==='cache'){
    if(!window.caches||typeof window.caches.open!=='function')throw new Error('Caché local no disponible.');
    handle.cache=await tf34Timed(window.caches.open(TF34_CACHE_NAME),4000,'No se pudo abrir la caché de música.');
   }else if(mode==='opfs'){
    if(!navigator.storage||typeof navigator.storage.getDirectory!=='function')throw new Error('Archivos privados no disponibles.');
    const dir=await tf34Timed(navigator.storage.getDirectory(),4000,'No se pudo abrir el directorio de música.');
    handle.dir=await tf34Timed(dir.getDirectoryHandle('taskflow_audio_t34',{create:true}),4000,'No se pudo abrir la carpeta de música.');
   }
   if(mode!=='memory')for(const store of [STORE_TRACKS,STORE_META])for(const value of tf34Memory[store].values())await tf34DirectPut(handle,store,value);
   tf34RememberBackend(handle);return;
  }catch(e){try{if(handle.native)handle.native.close()}catch(_){}handle.native=null;console.warn('TaskFlow: alternativa de música no disponible',e)}
 }
