}
async function tf34NextStore(handle,error){
 if(handle.recovery)return handle.recovery;
 const next=handle.mode==='indexeddb'?['cache','opfs','memory']:handle.mode==='cache'?['opfs','memory']:['memory'];
 handle.recovery=tf34SelectStore(handle,next,error);
 try{await handle.recovery}finally{handle.recovery=null}
}
async function openDb(){
 const handle={__tf34Audio:true,mode:'indexeddb',generation:0,recovery:null,native:null,cache:null,dir:null,close(){try{if(this.native)this.native.close()}catch(_){}}};
 let preferred='';try{preferred=localStorage.getItem(TF34_BACKEND_KEY)||''}catch(_){}
 const order=preferred==='cache'?['cache','indexeddb','opfs','memory']:preferred==='opfs'?['opfs','indexeddb','cache','memory']:['indexeddb','cache','opfs','memory'];
 await tf34SelectStore(handle,order);return handle;
}
async function idbGet(handle,store,key){
 if(tf34Memory[store].has(key))return tf34Memory[store].get(key);
 while(true){
  if(handle.recovery)await handle.recovery;const generation=handle.generation;
  try{const value=await tf34DirectGet(handle,store,key);if(value)tf34Memory[store].set(key,value);return value||null}
  catch(e){if(generation===handle.generation)await tf34NextStore(handle,e);if(tf34Memory[store].has(key))return tf34Memory[store].get(key);if(handle.mode==='memory')return null}
 }
}
async function idbPut(handle,store,value){
 const key=store===STORE_TRACKS?value.id:value.key;tf34Memory[store].set(key,value);
 while(true){if(handle.recovery)await handle.recovery;const generation=handle.generation;try{return await tf34DirectPut(handle,store,value)}catch(e){if(generation===handle.generation)await tf34NextStore(handle,e)}}
}
async function tf34SaveInstall(handle,phase,resetAt){
 const state={phase,resetAt,signature:PACK_SIGNATURE,at:Date.now()};
 try{localStorage.setItem(TF34_INSTALL_KEY,JSON.stringify(state))}catch(_){}
