function tf34BindResetLifecycle(){
 document.addEventListener('click',event=>{
  if(!event.target.closest||!event.target.closest('#tf120ResetConfirm'))return;
  const status=document.getElementById('tf120ResetStatus');if(!status)return;
  let timer=0;const observer=new MutationObserver(()=>{
   if(status.classList.contains('ok')&&status.textContent.trim()){
    try{localStorage.setItem(TF34_RESET_KEY,String(Date.now()))}catch(_){}
    tf36DefaultMusicOff();
    observer.disconnect();clearTimeout(timer);
   }else if(status.classList.contains('bad')){observer.disconnect();clearTimeout(timer)}
  });
  observer.observe(status,{attributes:true,attributeFilter:['class'],childList:true,subtree:true,characterData:true});
  timer=setTimeout(()=>observer.disconnect(),15000);
 },true);
}

