 downloadRunning=true;audioReady=false;tf34DialogAllowed=false;hideGate();
 let db;
 try{
  // Comprobar la música existente en silencio. Una apertura normal nunca abre el aviso.
  void requestPersistentStorage();
  db=await openDb();
